	"karimmi": "<p class=\"definition\" data-language=\"en\">Temple</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"karimmi\" data-language=\"ht\">karimmi</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"karimni\" data-language=\"ht\">karimni</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"karimmi\" data-language=\"ht\">karimmi</td> </tr>\n</table></p>",
	"kar\u016b": "<p class=\"definition\" data-language=\"en\">Already</p>",
	"katta": "<p class=\"definition\" data-language=\"en\">Down (as in katta t\u0113\u1e2b\u1e2bun, \"I put (something) down\")</p>",
