	"kattera": "<p class=\"definition\" data-language=\"en\">Lower</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"kattera\u0161\" data-language=\"ht\">kattera\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"katteri\" data-language=\"ht\">katteri</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"katteran\" data-language=\"ht\">katteran</td> </tr>\n</table></p>",
