	"l\u016bli": "<p class=\"definition\" data-language=\"en\">Pool, lake, basin, body of water</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"l\u016bli\u0161\" data-language=\"ht\">l\u016bli\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"l\u016bliya\" data-language=\"ht\">l\u016bliya</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"l\u016blin\" data-language=\"ht\">l\u016blin</td> </tr>\n</table></p>",
	"m": "<p class=\"definition\" data-language=\"en\">Man (individual man's name)</p>\n<p class=\"paradigm\" data-language=\"en\">This sign can be used as a \"determiner\": not pronounced, but marking what sort of thing the next word is.</p>",
	"mekki": "<p class=\"definition\" data-language=\"en\">Very</p>",
	"milit": "<p class=\"definition\" data-language=\"en\">Honey; this word is closely related to Latin <i>melle</i> with the same meaning</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\">Nom</td> <td class=\"htt word\" data-word=\"milit\" data-language=\"ht\">milit</td> </tr>\n\t<tr> <td class=\"eng\">Gen</td> <td class=\"htt word\" data-word=\"milita\u0161\" data-language=\"ht\">milita\u0161</td> </tr>\n</table></p>",
	"m\u0101n": "<p class=\"definition\" data-language=\"en\">When</p>",
	"n(u)": "<p class=\"definition\" data-language=\"en\">Then (a mostly-meaningless word used to introduce a new sentence in Hittite, called the \"sentence connective\".)</p>",
