	"\u0161\u0101ra": "<p class=\"definition\" data-language=\"en\">Up, above</p>",
	"\u0161\u0113r": "<p class=\"definition\" data-language=\"en\">On (top of)</p>",
	"\u1e2aattu\u0161umna": "<p class=\"definition\" data-language=\"en\">Hittite (adjective); literally, \"from the city of \u1e2aattu\u0161a\"</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2aattu\u0161umna\u0161\" data-language=\"ht\">\u1e2aattu\u0161umna\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2aattu\u0161umni\" data-language=\"ht\">\u1e2aattu\u0161umni</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2aattu\u0161umnan\" data-language=\"ht\">\u1e2aattu\u0161umnan</td> </tr>\n</table></p>",
	"\u1e2balki": "<p class=\"definition\" data-language=\"en\">Grain in general, or barley in particular</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\">Nom</td> <td class=\"htt word\" data-word=\"\u1e2balki\" data-language=\"ht\">\u1e2balki</td> </tr>\n\t<tr> <td class=\"eng\">Gen</td> <td class=\"htt word\" data-word=\"\u1e2balkiya\u0161\" data-language=\"ht\">\u1e2balkiya\u0161</td> </tr>\n</table></p>",
