	"\u1e2bal\u1e2baltomar": "<p class=\"definition\" data-language=\"en\">Corner</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bal\u1e2baltomar\" data-language=\"ht\">\u1e2bal\u1e2baltomar</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bal\u1e2baltomari\" data-language=\"ht\">\u1e2bal\u1e2baltomari</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bal\u1e2baltomar\" data-language=\"ht\">\u1e2bal\u1e2baltomar</td> </tr>\n</table></p>",
	"\u1e2bapa": "<p class=\"definition\" data-language=\"en\">River</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bapa\u0161\" data-language=\"ht\">\u1e2bapa\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bapi\" data-language=\"ht\">\u1e2bapi</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bapan\" data-language=\"ht\">\u1e2bapan</td> </tr>\n</table></p>",
	"\u1e2bappira": "<p class=\"definition\" data-language=\"en\">City</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bappira\u0161\" data-language=\"ht\">\u1e2bappira\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bappiri\" data-language=\"ht\">\u1e2bappiri</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bappiran\" data-language=\"ht\">\u1e2bappiran</td> </tr>\n</table></p>",
	"\u1e2bararazi": "<p class=\"definition\" data-language=\"en\">Mill, millstone (for grinding grain into flour)</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bararazi\" data-language=\"ht\">\u1e2bararazi</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bararaziya\" data-language=\"ht\">\u1e2bararaziya</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2bararazi\" data-language=\"ht\">\u1e2bararazi</td> </tr>\n</table></p>",
	"\u1e2barkun": "<p class=\"definition\" data-language=\"en\">I had, held (something: accusative)</p>",
	"\u1e2battalu": "<p class=\"definition\" data-language=\"en\">Door bar; key locks were not yet a common technology, so the best way to secure a door was to hold it shut with a big piece of wood.</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battalu\" data-language=\"ht\">\u1e2battalu</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battaluwi\" data-language=\"ht\">\u1e2battaluwi</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battalu\" data-language=\"ht\">\u1e2battalu</td> </tr>\n</table></p>",
	"\u1e2battalwan": "<p class=\"definition\" data-language=\"en\">Locked, bolted, held shut by something</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battalwanza\" data-language=\"ht\">\u1e2battalwanza</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battalwanti\" data-language=\"ht\">\u1e2battalwanti</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2battalwantan\" data-language=\"ht\">\u1e2battalwantan</td> </tr>\n</table></p>",
	"\u1e2ba\u0161\u0161a": "<p class=\"definition\" data-language=\"en\">Hearth, fireplace</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161a\u0161\" data-language=\"ht\">\u1e2ba\u0161\u0161a\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161i\" data-language=\"ht\">\u1e2ba\u0161\u0161i</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161an\" data-language=\"ht\">\u1e2ba\u0161\u0161an</td> </tr>\n</table></p>",
	"\u1e2ba\u0161\u0161u": "<p class=\"definition\" data-language=\"en\">King</p>\n<p class=\"paradigm\" data-language=\"en\"><table class=\"paradigm\">\n\t<tr> <td class=\"eng\"><abbr title=\"Nominative: subject of a verb\">Nom</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161u\u0161\" data-language=\"ht\">\u1e2ba\u0161\u0161u\u0161</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Dative: location or destination\">Dat</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161ui\" data-language=\"ht\">\u1e2ba\u0161\u0161ui</td> </tr>\n\t<tr> <td class=\"eng\"><abbr title=\"Accusative: object of a verb\">Acc</abbr></td> <td class=\"htt word\" data-word=\"\u1e2ba\u0161\u0161un\" data-language=\"ht\">\u1e2ba\u0161\u0161un</td> </tr>\n</table></p>",
	"\u1e2ba\u0161\u1e2bun": "<p class=\"definition\" data-language=\"en\">I opened (something: accusative)</p>",
